/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: VideosPage
 * Internal
 *   Functions: GridFallback
 *   Constants: VideoPreviewGrid, VideoPreviewSettings
 * @end-catalog */

import { useInfiniteQuery, useQuery } from '@tanstack/react-query';
import { lazy, Suspense, useMemo, useState } from 'react';
import { Grid2X2, PanelsTopLeft } from 'lucide-react';

import { getListenerVideos, listenerVideosQueryKey } from '../../api/listenerVideos';
import { ApiError } from '../../api/client';
import { browserSessionQuery } from '../../api/session';
// The Grid reuses PageSection, not ContentCard alone, so the shared card chunk is not split for this route.
import { PageSection } from '../../components/PageSection';
import { formatLocalizedMessage, useLocalization } from '../../localization/LocalizationProvider';
import { launchStandalonePlayback } from '../playback/launchPlayback';
import type { VideoPreviewGridProps } from './VideoPreviewGrid';
import { useVideosView } from './useVideosView';
import { videoTextFor } from './videoText';
import pageStyles from '../../styles/Pages.module.css';
import styles from './VideosPage.module.css';

/** Keeps the default Grid available if an old tab can no longer load the optional view chunk. */
const GridFallback = ({ items, onPlay }: VideoPreviewGridProps) => {
  const { t } = useLocalization();
  return <PageSection cardFrame="wide" id="videos" items={items} onPlay={onPlay} presentation="grid" title={t('common.label.video')} />;
};
// Save/framing controls are optional route code; they do not expand the reviewed initial-JS budget.
const VideoPreviewGrid = lazy(() => import('./VideoPreviewGrid').catch(() => ({ default: GridFallback })));
// A stale optional settings chunk must not take down browsing or the shared player.
const VideoPreviewSettings = lazy(() => import('./VideoPreviewSettings').catch(() => ({ default: () => <></> })));

/** Shares one paginated Video collection between the compact Grid and immersive preview view. */
export const VideosPage = () => {
  const { t, locale } = useLocalization();
  const text = videoTextFor(locale, formatLocalizedMessage);
  const [restartGeneration, setRestartGeneration] = useState(0);
  const viewerId = useQuery(browserSessionQuery()).data?.user.id;
  const videos = useInfiniteQuery({
    queryKey: restartGeneration ? [...listenerVideosQueryKey, restartGeneration] : listenerVideosQueryKey,
    queryFn: ({ pageParam, signal }) => getListenerVideos(pageParam, signal),
    initialPageParam: undefined as string | undefined,
    getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined
  });
  const [view, chooseView] = useVideosView(videos.data?.pages[0]?.defaultView);
  // A changed order or visibility snapshot cannot continue through its old cursor.
  const restartRequired = videos.error instanceof ApiError && videos.error.status === 409;
  const title = t('common.label.video');
  const items = useMemo(() => videos.data?.pages.flatMap((page) => page.items) ?? [], [videos.data]);

  return (
    <div className={`${pageStyles.page} ${styles.page}`}>
      <header className={styles.header}>
        <h1 className={pageStyles.pageTitle}>{title}</h1>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '.5rem', alignItems: 'center', maxWidth: '100%' }}>
          <div aria-label={text('videos.view.label')} className={styles.viewSwitch} role="group">
            <button aria-pressed={view === 'grid'} onClick={() => chooseView('grid')} type="button">
              <Grid2X2 aria-hidden="true" size={17} />{text('videos.view.grid')}
            </button>
            <button aria-pressed={view === 'immersive'} onClick={() => chooseView('immersive')} type="button">
              <PanelsTopLeft aria-hidden="true" size={18} />{text('videos.view.immersive')}
            </button>
          </div>
          <Suspense fallback={null}><VideoPreviewSettings /></Suspense>
        </div>
      </header>

      {videos.isPending ? (
        <section className={pageStyles.panel} aria-busy="true">
          <p className={pageStyles.panelTitle}>{t('home.loading.title')}</p>
        </section>
      ) : videos.isError && !videos.data ? (
        <section className={pageStyles.panel} role="alert">
          <div>
            <p className={pageStyles.panelCopy}>{t('home.error.copy')}</p>
            <div className={`${pageStyles.actions} ${pageStyles.panelActions}`}>
              <button className={`${pageStyles.button} ${pageStyles.buttonSecondary}`} onClick={() => { void videos.refetch(); }} type="button">
                {t('common.action.try_again')}
              </button>
            </div>
          </div>
        </section>
      ) : (
        <>
          {videos.isRefetchError && (
            <section className={pageStyles.panel} role="alert">
              <p className={pageStyles.panelCopy}>{t('home.error.copy')}</p>
              <button className={`${pageStyles.button} ${pageStyles.buttonSecondary}`} onClick={() => { void videos.refetch(); }} type="button">
                {t('common.action.try_again')}
              </button>
            </section>
          )}
          {view === 'grid' ? <PageSection
            cardFrame="wide"
            id="videos"
            items={items}
            onPlay={(track) => { void launchStandalonePlayback(track, viewerId); }}
            presentation="grid"
            title={title}
          /> : <Suspense fallback={<section aria-busy="true"><p className={pageStyles.panelCopy}>{t('home.loading.title')}</p></section>}>
            <VideoPreviewGrid items={items} onPlay={(track) => { void launchStandalonePlayback(track, viewerId); }} viewerId={viewerId} />
          </Suspense>}
          {(videos.hasNextPage || videos.isFetchNextPageError) && (
            <div className={styles.pagination}>
              {videos.isFetchNextPageError && <p role="alert">{t('home.error.copy')}</p>}
              <button
                className={`${pageStyles.button} ${pageStyles.buttonSecondary}`}
                disabled={videos.isFetchingNextPage}
                onClick={() => { if (restartRequired) setRestartGeneration(value => value + 1); else void videos.fetchNextPage(); }}
                type="button"
              >
                {videos.isFetchingNextPage ? t('common.state.loading_more') : restartRequired ? t('common.action.try_again') : t('common.action.load_more')}
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
};
